/* mOS — os tipos de swift/shims/SwiftStdint.h que as tabelas Unicode do Swift usam (libSystem freestanding e host) */
#ifndef SWIFT_UNICODE_TYPES_H
#define SWIFT_UNICODE_TYPES_H
typedef unsigned char __swift_uint8_t;
typedef unsigned short __swift_uint16_t;
typedef unsigned int __swift_uint32_t;
typedef int __swift_int32_t;
typedef unsigned long long __swift_uint64_t;
typedef long __swift_intptr_t;
#endif
